package com.example.library.service;

import com.example.library.entity.Book;
import com.example.library.exception.BookNotFoundException;
import com.example.library.exception.DuplicateIsbnException;
import com.example.library.repository.BookRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Transactional
public class BookService {

    private final BookRepository bookRepository;

    public BookService(BookRepository bookRepository) {
        this.bookRepository = bookRepository;
    }

    public Book addBook(Book book) {
        if (bookRepository.existsByIsbn(book.getIsbn())) {
            throw new DuplicateIsbnException("ISBN already exists: " + book.getIsbn());
        }
        if (book.getInventoryCount() < 0) {
            throw new IllegalArgumentException("Inventory count cannot be negative");
        }
        return bookRepository.save(book);
    }

    @Transactional(readOnly = true)
    public List<Book> getAllBooks() {
        return bookRepository.findAll();
    }

    @Transactional(readOnly = true)
    public Book getBookById(Long id) {
        return bookRepository.findById(id)
                .orElseThrow(() -> new BookNotFoundException("Book not found with id: " + id));
    }

    public Book updateBook(Long id, Book bookDetails) {
        Book book = getBookById(id);
        book.setTitle(bookDetails.getTitle());
        book.setAuthor(bookDetails.getAuthor());
        // ISBN is not updatable to maintain uniqueness; if needed, separate endpoint can be added
        return bookRepository.save(book);
    }

    public void deleteBook(Long id) {
        Book book = getBookById(id);
        bookRepository.delete(book);
    }

    public void decreaseInventory(Book book) {
        if (book.getInventoryCount() <= 0) {
            throw new IllegalStateException("Book inventory is zero, cannot borrow");
        }
        book.setInventoryCount(book.getInventoryCount() - 1);
        bookRepository.save(book);
    }

    public void increaseInventory(Book book) {
        book.setInventoryCount(book.getInventoryCount() + 1);
        bookRepository.save(book);
    }
}

package com.example.library.service;

import com.example.library.entity.Book;
import com.example.library.entity.BorrowedBook;
import com.example.library.repository.BorrowedBookRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional
public class BorrowService {

    private final BorrowedBookRepository borrowedBookRepository;
    private final BookService bookService;

    public BorrowService(BorrowedBookRepository borrowedBookRepository, BookService bookService) {
        this.borrowedBookRepository = borrowedBookRepository;
        this.bookService = bookService;
    }

    public Book borrowBook(Long bookId) {
        Book book = bookService.getBookById(bookId);
        bookService.decreaseInventory(book);
        BorrowedBook borrowedBook = new BorrowedBook(book);
        borrowedBookRepository.save(borrowedBook);
        return book;
    }

    public Book returnBook(Long bookId) {
        Book book = bookService.getBookById(bookId);
        // We don't require a specific borrow record; just increase inventory
        bookService.increaseInventory(book);
        // Mark the latest unreturned borrow record as returned (optional)
        return book;
    }
}

package com.example.library.controller;

import com.example.library.entity.Book;
import com.example.library.service.BookService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/books")
public class BookController {

    private final BookService bookService;

    public BookController(BookService bookService) {
        this.bookService = bookService;
    }

    @PostMapping
    public ResponseEntity<Book> addBook(@Valid @RequestBody Book book) {
        Book created = bookService.addBook(book);
        return ResponseEntity.status(HttpStatus.CREATED).body(created);
    }

    @GetMapping
    public ResponseEntity<List<Book>> getAllBooks() {
        return ResponseEntity.ok(bookService.getAllBooks());
    }

    @GetMapping("/{id}")
    public ResponseEntity<Book> getBookById(@PathVariable Long id) {
        return ResponseEntity.ok(bookService.getBookById(id));
    }

    @PutMapping("/{id}")
    public ResponseEntity<Book> updateBook(@PathVariable Long id, @Valid @RequestBody Book book) {
        Book updated = bookService.updateBook(id, book);
        return ResponseEntity.ok(updated);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteBook(@PathVariable Long id) {
        bookService.deleteBook(id);
        return ResponseEntity.noContent().build();
    }
}

