package com.example.library.service;

import com.example.library.entity.Book;
import com.example.library.exception.BookNotFoundException;
import com.example.library.exception.DuplicateIsbnException;
import com.example.library.repository.BookRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class BookServiceTest {

    @Mock
    private BookRepository bookRepository;

    @InjectMocks
    private BookService bookService;

    private Book book;

    @BeforeEach
    void setUp() {
        book = new Book("Test Title", "Test Author", "123-4567890123", 5);
        book.setId(1L);
    }

    @Test
    void addBookSuccess() {
        when(bookRepository.existsByIsbn(book.getIsbn())).thenReturn(false);
        when(bookRepository.save(any(Book.class))).thenReturn(book);

        Book saved = bookService.addBook(book);

        assertThat(saved).isNotNull();
        assertThat(saved.getIsbn()).isEqualTo(book.getIsbn());
        verify(bookRepository).save(any(Book.class));
    }

    @Test
    void addBookDuplicateIsbnThrows() {
        when(bookRepository.existsByIsbn(book.getIsbn())).thenReturn(true);

        assertThatThrownBy(() -> bookService.addBook(book))
                .isInstanceOf(DuplicateIsbnException.class)
                .hasMessageContaining("ISBN already exists");
    }

    @Test
    void getBookByIdSuccess() {
        when(bookRepository.findById(1L)).thenReturn(Optional.of(book));

        Book found = bookService.getBookById(1L);

        assertThat(found).isEqualTo(book);
    }

    @Test
    void getBookByIdNotFoundThrows() {
        when(bookRepository.findById(1L)).thenReturn(Optional.empty());

        assertThatThrownBy(() -> bookService.getBookById(1L))
                .isInstanceOf(BookNotFoundException.class)
                .hasMessageContaining("Book not found");
    }

    @Test
    void decreaseInventorySuccess() {
        book.setInventoryCount(1);
        when(bookRepository.save(any(Book.class))).thenReturn(book);

        bookService.decreaseInventory(book);

        assertThat(book.getInventoryCount()).isEqualTo(0);
        verify(bookRepository).save(book);
    }

    @Test
    void decreaseInventoryZeroThrows() {
        book.setInventoryCount(0);

        assertThatThrownBy(() -> bookService.decreaseInventory(book))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("inventory is zero");
    }
}

package com.example.library.service;

import com.example.library.entity.Book;
import com.example.library.exception.BookNotFoundException;
import com.example.library.repository.BorrowedBookRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class BorrowServiceTest {

    @Mock
    private BorrowedBookRepository borrowedBookRepository;

    @Mock
    private BookService bookService;

    @InjectMocks
    private BorrowService borrowService;

    private Book book;

    @BeforeEach
    void setUp() {
        book = new Book("Borrow Test", "Author", "321-0987654321", 3);
        book.setId(1L);
    }

    @Test
    void borrowBookSuccess() {
        when(bookService.getBookById(1L)).thenReturn(book);
        doAnswer(invocation -> {
            book.setInventoryCount(book.getInventoryCount() - 1);
            return null;
        }).when(bookService).decreaseInventory(book);

        Book borrowed = borrowService.borrowBook(1L);

        assertThat(borrowed.getInventoryCount()).isEqualTo(2);
        verify(borrowedBookRepository).save(any());
    }

    @Test
    void borrowBookNotFoundThrows() {
        when(bookService.getBookById(1L)).thenThrow(new BookNotFoundException("Book not found"));

        assertThatThrownBy(() -> borrowService.borrowBook(1L))
                .isInstanceOf(BookNotFoundException.class);
    }

    @Test
    void returnBookSuccess() {
        when(bookService.getBookById(1L)).thenReturn(book);
        doAnswer(invocation -> {
            book.setInventoryCount(book.getInventoryCount() + 1);
            return null;
        }).when(bookService).increaseInventory(book);

        Book returned = borrowService.returnBook(1L);

        assertThat(returned.getInventoryCount()).isEqualTo(4);
    }
}

package com.example.library.controller;

import com.example.library.entity.Book;
import com.example.library.repository.BookRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;

import static org.hamcrest.Matchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest
@AutoConfigureMockMvc
@ActiveProfiles("test")
class BookControllerIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private BookRepository bookRepository;

    @Autowired
    private ObjectMapper objectMapper;

    @BeforeEach
    void setUp() {
        bookRepository.deleteAll();
    }

    @Test
    void addBookAndGetById() throws Exception {
        Book book = new Book("Integration Title", "Integration Author", "111-2223334445", 10);

        mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(book)))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.id").isNumber())
                .andExpect(jsonPath("$.title").value("Integration Title"));

        // Verify we can get it
        mockMvc.perform(get("/books/1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.isbn").value("111-2223334445"));
    }

    @Test
    void addDuplicateIsbnReturnsBadRequest() throws Exception {
        Book book1 = new Book("One", "Author1", "DUPLICATE-ISBN", 1);
        bookRepository.save(book1);

        Book book2 = new Book("Two", "Author2", "DUPLICATE-ISBN", 1);

        mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(book2)))
                .andExpect(status().isBadRequest());
    }

    @Test
    void borrowAndReturnIntegration() throws Exception {
        Book book = new Book("Borrowable", "Author B", "ISBN-BORROW-001", 2);
        Book saved = bookRepository.save(book);

        mockMvc.perform(post("/borrow")
                        .param("bookId", saved.getId().toString()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.inventoryCount").value(1));

        mockMvc.perform(post("/borrow/return")
                        .param("bookId", saved.getId().toString()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.inventoryCount").value(2));
    }

    @Test
    void borrowWhenInventoryZeroReturnsBadRequest() throws Exception {
        Book book = new Book("OutOfStock", "Author O", "ISBN-OUT-001", 0);
        Book saved = bookRepository.save(book);

        mockMvc.perform(post("/borrow")
                        .param("bookId", saved.getId().toString()))
                .andExpect(status().isBadRequest());
    }
}
